def G(code):
    return 'if __name__ == "__main__":\n' + textwrap.indent(clean(code), '    ')


L(2, '1. Start an importable process worker with spawn',
  'Protect the entry point and transfer a small result explicitly.',
  [('Process; spawn context', 'A process has a separate interpreter/address space. spawn starts a fresh interpreter and imports the required definitions rather than sharing the parent execution stack.'),
   ('Main guard; importable worker', 'Only start child work under if __name__ == "__main__". Put worker targets in a real importable module, not a local lambda or notebook-only definition.'),
   ('emit_square; multiprocessing.Queue', 'The supplied worker places one result on an explicit process communication queue. Ordinary return values from a raw Process do not become join results.')],
  "Separate interpreters can execute independent CPU work using available resources even on ordinary GIL-enabled CPython. That independence also means state and results need explicit transfer. The first example uses a small queue and a module-level worker.\n\nOn Windows, a child imports the program entry path. Unguarded process creation can recursively start more children. The saved-script guard is part of the example, not an optional decoration. The supplied workers.py must remain beside the practice script.\n\nThe owner receives the result, joins the process, closes its handle and closes the queue. The helper performs finite work, so joining is a deliberate lifetime boundary. Do not use forceful termination as a normal substitute for cleanup.",
  G('import multiprocessing as mp\nfrom workers import emit_square\ncontext = mp.get_context("spawn")\nqueue = context.Queue()\np = context.Process(target=emit_square, args=(7, queue))\np.start()\ntry:\n    print("Transferred result:", queue.get(timeout=5))\nfinally:\n    p.join()\n    print("Successful exit:", p.exitcode == 0)\n    p.close()\n    queue.close()\n    queue.join_thread()'),
  'Run an importable worker through a spawn process executor.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import square\nwith ProcessPoolExecutor(max_workers=1, mp_context=mp.get_context("spawn")) as pool:\n    print(list(pool.map(square, [2, 3, 4])))'),
  'Explain why a nested lambda is not a portable spawn-worker contract.',
  'print("A child must import/reconstruct its worker")\nprint("Use a module-level named function and a protected saved-script entry point")',
  [('Why protect process creation with a main guard?', 'A spawned child imports the entry path', 'To disable every thread', 'To make globals shared', 'Importing the program must not recursively launch child jobs.'),
   ('Does raw Process.join return the target result?', 'No', 'Always', 'Only when a queue exists', 'Use an explicit queue or a future result.')],
  'Launch process work from an unguarded module or a notebook-only local target.', 'Use an importable worker and own process/queue lifetimes.',
  'The queue transfers 49 and the joined child exits successfully. The displayed guard is required for safe script reuse.',
  syntax='if __name__ == "__main__":\n    context = multiprocessing.get_context("spawn")\n    process = context.Process(target=importable_worker)')

L(2, '2. Treat ordinary process globals as isolated state',
  'Transfer facts back instead of expecting child mutation to change the parent.',
  [('Process-local globals', 'A spawned worker imports its own module state. Changing an ordinary global there does not update the parent module.'),
   ('child_increment; process_identity', 'The supplied functions demonstrate local counter mutation and return a child process id alongside a computed value. Assignment of jobs to workers is not a fixed promise.')],
  "A variable named CHILD_COUNTER in a worker module is not a shared counter across all interpreters. Each spawned process begins with its imported state and can change that state locally. Results returned through communication are separate from parent memory mutation.\n\nDo not assert that each submitted job runs on a different process or that every worker handles exactly one item. Scheduling and startup can distribute small jobs unevenly. Keep identity diagnostics separate from the actual result contract.\n\nThe example submits one counter change to one child and checks the parent remains zero. A second exercise checks that returned process ids differ from the parent without printing machine-specific ids as reusable expected values.",
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nimport workers\nwith ProcessPoolExecutor(max_workers=1, mp_context=mp.get_context("spawn")) as pool:\n    child_value = pool.submit(workers.child_increment).result()\nprint("Child local counter:", child_value)\nprint("Parent counter unchanged:", workers.CHILD_COUNTER)'),
  'Verify successful work executes outside the parent process.',
  G('import os\nimport multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import process_identity\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    rows = list(pool.map(process_identity, [2, 3]))\nprint("Values:", [r["value"] for r in rows])\nprint("All child processes:", all(r["pid"] != os.getpid() for r in rows))'),
  'State why counting returned distinct pids is not a required worker-utilization guarantee.',
  'print("A pool can assign several small jobs to one ready worker")\nprint("Correctness must not depend on a fixed job-to-process schedule")',
  [('Does a child global assignment automatically update the parent?', 'No', 'Always', 'Only if the names match', 'The ordinary module dictionaries belong to separate interpreters.'),
   ('Must two tiny submitted jobs use two distinct workers?', 'No', 'Always', 'Only when max_workers is two', 'Worker availability and scheduling determine assignment.')],
  'Use ordinary globals as inter-process communication or depend on a fixed worker schedule.', 'Return/transfer explicit results and separate scheduling from correctness.',
  'One child increments its local module counter; the parent value is unchanged.',
  syntax='child_result = pool.submit(module_worker, input_data).result()')

L(2, '3. Use explicit shared state only when justified',
  'Protect shared read-modify-write with the synchronization belonging to that shared object.',
  [('multiprocessing.Value; get_lock', 'An explicit shared numeric value can carry an associated process-safe lock. Reading and assigning individually is not the same as protecting their combined update.'),
   ('Local reduction alternative', 'For many problems, processes return independent partial results and the parent reduces them, avoiding shared mutation altogether.')],
  "Explicit shared objects are different from ordinary globals. A shared Value can store one numeric total across processes, but the compound increment still needs a lock around read and write. Its synchronized property access alone is not the complete multi-step transaction.\n\nThe example passes a shared object when starting two explicit processes and uses its own get_lock. Do not assume every shared object can simply be submitted through an arbitrary pool task interface; construction and transfer rules matter.\n\nOften a simpler design is to compute partial values and sum them in the parent. This reduces communication and contention and makes failure handling more explicit. Choose shared memory only when the workload actually benefits from it.",
  G('import multiprocessing as mp\nfrom workers import increment_shared\ncontext = mp.get_context("spawn")\nshared = context.Value("i", 0)\nprocesses = [context.Process(target=increment_shared, args=(shared, 500)) for _ in range(2)]\nfor p in processes: p.start()\nfor p in processes: p.join()\nprint("Shared protected total:", shared.value)\nprint("All successful:", all(p.exitcode == 0 for p in processes))\nfor p in processes: p.close()'),
  'Compute independent process results and reduce in the parent.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import square\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    parts = list(pool.map(square, [1, 2, 3, 4]))\nprint("Parent reduction:", sum(parts))'),
  'Explain why individual synchronized property access is insufficient for a compound update.',
  'print("Read and write are distinct operations")\nprint("Hold the same shared lock around the entire read-modify-write invariant")',
  [('Does shared.value += 1 become a whole transaction merely because Value is synchronized?', 'No; protect the compound operation', 'Always', 'Only for positive integers', 'Read and write must share one critical section.'),
   ('Can independent results avoid the shared counter?', 'Yes', 'No', 'Only with threads', 'The parent can combine explicit partial results.')],
  'Confuse explicit shared memory with ordinary globals or omit its compound-operation lock.', 'Prefer independent results where possible and synchronize real shared invariants.',
  'Two processes each perform five hundred protected increments on the same shared value.',
  syntax='with shared_value.get_lock():\n    shared_value.value += amount')

L(2, '4. Include startup and transfer in CPU comparisons',
  'Measure the same pure-Python work without guaranteeing processes win small jobs.',
  [('cpu_benchmark', 'The supplied helper computes equal eight-job outputs sequentially, with two threads and with two spawn processes. Each timed run includes its complete pool lifetime.'),
   ('Serialization and dispatch overhead', 'Worker inputs/results must cross the process boundary. Tiny jobs can cost less than the startup and transfer needed to parallelize them.')],
  "Independent CPU work can benefit from separate interpreters on available resources, but parallelism is not free. Starting processes, importing code and transferring small records can dominate short jobs. Batching changes that tradeoff and should be measured rather than assumed.\n\nThe helper uses the same pure-Python arithmetic for every strategy and checks identical outputs. This is intentionally not a native hash/compression call that might release the GIL and answer a different threading question.\n\nThe example uses a short one-trial budget to inspect the interface. The milestone retains repeated raw samples. A slower process result remains valid evidence about this task size; do not increase or cherry-pick work until a preferred method appears to win and hide the earlier runs.",
  G('from lab import cpu_benchmark\nr = cpu_benchmark(rounds=50000, repeats=1)\nprint("Jobs / rounds:", r["jobs"], r["rounds_per_job"])\nprint("Observed seconds:", {k: round(v, 3) for k, v in r["median_seconds"].items()})\nprint("Startup/transfer/shutdown included")'),
  'Check equal scoring across direct and process execution.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import score_payload\np = {"id": 2, "value": 39}\nexpected = score_payload(p, 1000)\nwith ProcessPoolExecutor(max_workers=1, mp_context=mp.get_context("spawn")) as pool:\n    actual = pool.submit(score_payload, p, 1000).result()\nprint("Parity:", actual == expected)'),
  'List three reasons more process workers can be slower.',
  'for reason in ["startup/import cost", "serialization and transfer", "limited CPU quota", "too-small jobs and coordination"]:\n    print(reason)',
  [('May a correct process version be slower on tiny jobs?', 'Yes', 'No', 'Only when results are wrong', 'Coordination can exceed useful parallel computation.'),
   ('Should the comparison silently replace Python arithmetic with a native kernel?', 'No', 'Always', 'Only for hashing', 'That changes the workload and potentially its GIL behavior.')],
  'Promise a fixed process speedup or omit lifecycle costs from a full-run claim.', 'Measure equal complete work under the actual job and resource budget.',
  'The timings describe this short CPU experiment and do not assert that any strategy must win.',
  syntax='with ProcessPoolExecutor(mp_context=get_context("spawn")) as pool:\n    results = list(pool.map(importable_worker, inputs))')

L(2, '5. Propagate process failures and own shutdown',
  'Receive a worker exception through a future and let finite work finish cleanly.',
  [('Remote exception delivery', 'A process future can transport a serializable worker exception to result(). It is different from the exit code of a raw Process.'),
   ('Pool shutdown', 'Executor scope exit joins owned work. Cancelling queued work does not forcibly interrupt a function that is already executing in a worker.')],
  "A process failure must not silently turn into a missing result or a fabricated zero. Future.result raises the transported exception so the owner can apply its error policy. A raw process instead exposes lifetime/exit information and needs its own result channel.\n\nThe example submits a worker that deliberately raises ValueError, catches it in the parent and then successfully completes another independent job. Not every failure leaves a pool usable: abrupt worker termination can break a pool, which requires a separate recovery policy.\n\nAvoid treating terminate as a graceful general cancellation tool. It can interrupt updates or cleanup at an arbitrary point. Use bounded work, cooperative protocols where needed and explicit ownership. Day 4 separates future waiting timeouts from real job cancellation.",
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import fail_job, square\nwith ProcessPoolExecutor(max_workers=1, mp_context=mp.get_context("spawn")) as pool:\n    failed = pool.submit(fail_job, "invalid task")\n    try:\n        failed.result()\n    except ValueError as exc:\n        print("Parent received:", str(exc))\n    print("Independent successful result:", pool.submit(square, 5).result())'),
  'Keep the exception visible instead of converting it into success.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import fail_job\nwith ProcessPoolExecutor(max_workers=1, mp_context=mp.get_context("spawn")) as pool:\n    future = pool.submit(fail_job, "bad record")\n    try:\n        future.result()\n    except ValueError:\n        print("Failed task recorded as failure")'),
  'Describe what forceful termination cannot promise.',
  'print("It cannot promise application cleanup completed")\nprint("It cannot undo prior side effects or preserve an interrupted multi-step update")',
  [('Where does a worker ValueError become visible in this interface?', 'At future.result in the owner', 'Only in an unrelated global', 'It always becomes zero', 'A future carries a result or an exception.'),
   ('Does cancellation automatically interrupt an already running process function?', 'No', 'Always', 'Only for a short function', 'Queued and running work have different cancellation capabilities.')],
  'Treat absent output as success or rely on forceful termination for normal cleanup.', 'Propagate failures and define lifecycle/recovery policies explicitly.',
  'The ordinary transported failure remains visible; an independent task then returns 25.',
  syntax='future = pool.submit(importable_worker, data)\nresult = future.result()  # may raise the worker exception')

L(2, '6. Keep the parent as coordinator of process work',
  'Send compact immutable-by-convention payloads and preserve result identities.',
  [('Parent coordination', 'The owner submits work, collects results, applies ordering/error policy and closes the pool. Workers focus on bounded computations.'),
   ('Transfer boundary', 'Serialized inputs/results cross interpreter boundaries. Large shared graphs, open handles and hidden mutable state complicate that contract.')],
  "A clean worker accepts a small validated payload and returns an identified result. It does not reach into browser progress or depend on a parent's live HTTP client. The parent owns transport, sequencing and output reporting.\n\nOur process worker receives just id/value and a declared round count. The queueing/transfer overhead is included in full-run measurements. Keep enough work per dispatch to justify that overhead rather than submitting an enormous number of trivial tasks.\n\nDo not make worker correctness depend on job assignment, an inherited socket or a nested call into the same saturated pool. Tomorrow's futures interface gives a common coordination model for threads and processes; the underlying state/transfer rules remain different.",
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import score_payload\npayloads = [{"id": i, "value": i*17+5} for i in range(4)]\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    rows = list(pool.map(score_payload, payloads, [1000]*4))\nprint("Result ids:", [row["id"] for row in rows])\nprint("Reference parity:", rows == [score_payload(p, 1000) for p in payloads])'),
  'Describe a compact CPU-worker boundary.',
  'contract = {"input": "validated id/value plus work count", "output": "id and deterministic score", "not transferred": "live HTTP client or learner state"}\nfor name, value in contract.items(): print(name + ": " + value)',
  'Compare ordered process map output with its input ids.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import square\nvalues = [4, 1, 3]\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    print(list(pool.map(square, values)))'),
  [('Should a CPU worker depend on the parent HTTP client object?', 'No', 'Always', 'Only when the host is local', 'Transport/resource ownership stays in the coordinating process.'),
   ('Does a common pool interface make thread and process state sharing identical?', 'No', 'Always', 'Only with map', 'The interface hides scheduling details, not ownership/transfer semantics.')],
  'Send hidden live resources across a spawn boundary or depend on worker scheduling.', 'Use explicit compact payloads and keep coordination in the owner.',
  'Each returned id remains paired with its deterministic score after transfer.',
  syntax='payload -> spawn worker -> identified result -> parent ordering/reduction',
  diagram=('Spawn workers and the import boundary', ['Protected parent creates a spawn pool', 'Each child imports worker definitions safely', 'Compact inputs cross the serialization boundary', 'Worker returns a result or transported exception', 'Parent collects, verifies and joins its pool'], 'Children have separate ordinary globals. Explicit communication or deliberately synchronized shared objects are different from thread-shared memory.'))

L(3, '1. Represent work with futures',
  'Separate submission, running/completion state and result delivery.',
  [('Future; submit; result', 'A future represents a pending/running/completed call. submit returns it; result waits for and returns its output or raises its stored exception.'),
   ('ThreadPoolExecutor', 'Owns a bounded set of worker threads. Its context manager waits for owned work on exit; limiting workers alone does not necessarily bound all submitted futures.')],
  "Futures make result/error delivery explicit without manually maintaining a result queue for each thread. submit does not return the worker's eventual result; it returns a handle to that eventual outcome.\n\nA future can already be complete by the time you inspect it. Avoid tests that assume a tiny job must still be running. The stable contract is the returned value or exception, not an accidental scheduling snapshot.\n\nThe executor owns worker lifetime. Leaving the with block waits for its submitted work according to shutdown semantics. Later parts show why a result waiting timeout is not a command to stop a running worker.",
  'from concurrent.futures import ThreadPoolExecutor\nfrom workers import square\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    future = pool.submit(square, 7)\n    print("Result:", future.result())\n    print("Done after result:", future.done())',
  'Retrieve an exception through a thread future.',
  'from concurrent.futures import ThreadPoolExecutor\nfrom workers import fail_job\nwith ThreadPoolExecutor(max_workers=1) as pool:\n    f = pool.submit(fail_job, "bad input")\n    try: f.result()\n    except ValueError as exc: print(str(exc))',
  'Submit two independent tasks before collecting their results.',
  'from concurrent.futures import ThreadPoolExecutor\nfrom workers import square\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    futures = [pool.submit(square, n) for n in [2, 3]]\n    print([f.result() for f in futures])',
  [('Does submit return the eventual function value immediately?', 'No; it returns a Future', 'Always', 'Only for threads', 'Result delivery is a separate operation.'),
   ('Can a tiny task already be complete when inspected?', 'Yes', 'No', 'Only after executor shutdown', 'Scheduling can finish it before the next caller instruction.')],
  'Treat a future as the computed value or depend on a transient running-state observation.', 'Collect the explicit result/exception and own executor lifetime.',
  'The result call returns 49 and the future is complete afterward.',
  syntax='future = executor.submit(function, argument)\nvalue = future.result()')

L(3, '2. Choose input order or completion order deliberately',
  'Use map or as_completed while preserving job-to-result pairing.',
  [('executor.map', 'Produces results in input order, even if later jobs finish earlier. Iterating it can wait behind an earlier unfinished input.'),
   ('as_completed; future-to-id mapping', 'Yields futures as they finish. Keep a mapping back to original job identities rather than assigning meaning to completion position.')],
  "Ordered output is convenient, but it can delay visible progress behind one slow early job. Completion-order collection can report ready work sooner, provided ids remain attached. Neither interface determines which physical worker must run a job.\n\nThe example first uses map to preserve the sequence 3,1,2. Then it maps futures to ids and gathers completions, sorting only for a stable displayed summary. The actual completion order remains intentionally unspecified.\n\nOn the targeted Python 3.12/3.13 interface, map can submit/retain more work than the active worker count. Use a bounded submission policy when the source is large or when memory/control requirements demand it.",
  'from concurrent.futures import ThreadPoolExecutor, as_completed\nfrom workers import square\nvalues = [3, 1, 2]\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    print("Map input order:", list(pool.map(square, values)))\n    pending = {pool.submit(square, n): n for n in values}\n    completed = [(pending[f], f.result()) for f in as_completed(pending)]\nprint("Identified completions, sorted for display:", sorted(completed))',
  'Restore input order from an explicitly completion-ordered fixture.',
  'done = [(2, "c"), (0, "a"), (1, "b")]\nprint([value for index, value in sorted(done)])',
  'Confirm process map has the same ordered-output contract.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom workers import square\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    print(list(pool.map(square, [3, 1, 2])))'),
  [('Does map output automatically follow completion order?', 'No; it follows input order', 'Always', 'Only for processes', 'Output order is a documented interface choice.'),
   ('What should accompany a completion-order result?', 'Its original stable job identity', 'Its arrival position as a replacement id', 'Only worker count', 'Ready results must not be paired with the wrong inputs.')],
  'Assume arrival order equals input order or worker identity.', 'Choose output order and preserve explicit pairing.',
  'The final display sorts pairs for readability; it does not claim the underlying completions arrived in that order.',
  syntax='future_to_id = {executor.submit(work, job): job.id for job in jobs}\nfor future in as_completed(future_to_id):\n    consume(future_to_id[future], future.result())')

L(3, '3. Separate waiting timeout from job cancellation',
  'Know which pending work can be cancelled and which running work continues.',
  [('Future.result timeout', 'Limits caller waiting for that result call. The underlying function can continue after TimeoutError.'),
   ('Future.cancel; CancelledError', 'Cancellation can succeed before a future starts running. A running call is not forcibly interrupted by cancel.')],
  "A timeout on result says the caller waited long enough; it does not say the worker ended. In this example, an event proves the worker is already running. Cancellation therefore returns False, and the owner deliberately releases the finite worker before executor cleanup.\n\nA manually constructed pending Future demonstrates the cancellable state separately. It is not evidence that every submitted task will stay pending long enough to cancel. Small jobs can start immediately.\n\nDesign side effects and ownership with these limits in mind. Executor shutdown may still wait for running work after a result timeout. Bounded operations and cooperative stop checkpoints are different from abandoning the Future handle.",
  'import threading\nfrom concurrent.futures import ThreadPoolExecutor, TimeoutError\nstarted, release = threading.Event(), threading.Event()\ndef work():\n    started.set()\n    release.wait()\n    return 7\nwith ThreadPoolExecutor(max_workers=1) as pool:\n    f = pool.submit(work)\n    try:\n        started.wait()\n        try: f.result(timeout=0.001)\n        except TimeoutError: print("Caller wait timed out")\n        print("Cancel running call:", f.cancel())\n    finally:\n        release.set()\n    print("Eventual result:", f.result())',
  'Inspect a deliberately pending future cancellation without scheduling a race.',
  'from concurrent.futures import Future, CancelledError\nf = Future()\nprint("Pending cancellation:", f.cancel())\ntry: f.result()\nexcept CancelledError: print("Cancelled result is not success")',
  'State why losing the future reference does not undo side effects.',
  'print("The worker may still be executing")\nprint("Completed external side effects are not rolled back by abandoning a handle")',
  [('Does result(timeout=...) kill a worker on timeout?', 'No', 'Always', 'Only for threads', 'The timeout belongs to waiting, not forced execution control.'),
   ('Can cancel normally interrupt a function already running?', 'No', 'Always', 'Only if it returns an integer', 'Pending and running states have different cancellation capabilities.')],
  'Treat wait timeouts as hard execution deadlines or rollback.', 'Design bounded work and explicit cooperation, then join owned execution.',
  'The running call survives the waiting timeout and later returns after its release signal.',
  syntax='try:\n    value = future.result(timeout=deadline)\nexcept TimeoutError:\n    handle_wait_timeout_without_claiming_worker_stopped()')

L(3, '4. Bound outstanding futures, not just workers',
  'Use the supplied submission window without consuming the entire source up front.',
  [('bounded_map', 'The local helper submits at most a declared window of unconsumed futures, yields completion results and refills as the consumer progresses.'),
   ('FIRST_COMPLETED; backpressure', 'wait can return once some work is ready. A submission window limits queued work while a slow downstream consumer delays further source pulls.')],
  "A pool with two workers can still have a million waiting futures if the caller eagerly submits a million jobs. Worker limits and outstanding-work limits solve different problems. Keep both explicit.\n\nThe helper fills a small window, waits for completions and only requests more source items as results are consumed. Its unique exhaustion sentinel preserves legitimate None data. Completion ordering still needs explicit ids when it matters.\n\nThe example inspects source pulls after the first result to prove the entire twenty-item source was not consumed. Closing the generator cancels pending not-yet-running futures; the executor context still owns any already running calls.",
  'from concurrent.futures import ThreadPoolExecutor\nfrom collector import bounded_map\nfrom workers import square\nseen = []\ndef source():\n    for value in range(20):\n        seen.append(value)\n        yield value\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    results = bounded_map(pool, square, source(), limit=3)\n    first = next(results)\n    print("First belongs to initial window:", first in {0, 1, 4})\n    print("Source pulls before next request:", len(seen))\n    results.close()',
  'Show None remains ordinary input data in the bounded helper.',
  'from concurrent.futures import ThreadPoolExecutor\nfrom collector import bounded_map\nwith ThreadPoolExecutor(max_workers=1) as pool:\n    print(list(bounded_map(pool, lambda x: x, [None, 2], limit=1)))',
  'Use the same submission policy with process workers.',
  G('import multiprocessing as mp\nfrom concurrent.futures import ProcessPoolExecutor\nfrom collector import bounded_map\nfrom workers import square\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    print(sorted(bounded_map(pool, square, range(6), limit=3)))'),
  [('Does max_workers=2 alone bound all submitted futures to two?', 'No', 'Always', 'Only for a list source', 'The caller can queue much more work than the active workers.'),
   ('Why use a unique end sentinel rather than None here?', 'None can be legitimate source data', 'To make processes share globals', 'To force completion order', 'Exhaustion markers must not collide with data.')],
  'Submit the whole source eagerly while claiming a worker limit bounds retained jobs.', 'Bound the submission window and account for consumer progress.',
  'Only three source values were pulled before the first result was returned to the caller.',
  syntax='for result in bounded_map(executor, work, source, limit=window):\n    consume(result)')

L(3, '5. Keep dependencies outside a saturated worker pool',
  'Avoid nested waits that require the same unavailable worker capacity.',
  [('Executor deadlock', 'A worker can wait forever for another task submitted to the same fully occupied pool. With one worker, a waiting parent job leaves no worker for its child job.'),
   ('Coordinator-owned dependency graph', 'The owner schedules independent stages and combines their completed results rather than blocking a worker on work requiring that same saturated pool.')],
  "Consider a one-worker pool where its only task submits another task to that pool and waits for the new result. The child cannot run because the sole worker is occupied waiting. We describe this failure rather than executing an unbounded deadlock in the lesson.\n\nThe safe example lets the owner submit independent jobs and collect their results. Dependencies can be combined in the owner or represented by a deliberately designed orchestration model. Increasing workers may hide one small case but does not prove arbitrary nested dependencies safe.\n\nThe same reasoning applies to locks, blocking queues and resource cycles. Make ownership and dependency direction visible before choosing worker counts. Timeouts can reveal a wait but do not by themselves repair a cyclic design.",
  'from concurrent.futures import ThreadPoolExecutor\nfrom workers import square\nwith ThreadPoolExecutor(max_workers=1) as pool:\n    a = pool.submit(square, 2)\n    b = pool.submit(square, 3)\n    total = a.result()+b.result()\nprint("Owner combined independent jobs:", total)',
  'Express the deadlock dependency in text without launching it.',
  'print("Only worker waits for child future")\nprint("Child requires the same occupied worker")\nprint("Repair dependency ownership rather than waiting forever")',
  'Perform a second stage in the owner after the first futures complete.',
  'from concurrent.futures import ThreadPoolExecutor\nfrom workers import square\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    first = list(pool.map(square, [1, 2, 3]))\nprint("Owner second stage:", sum(first))',
  [('Is adding one worker proof that every nested dependency is safe?', 'No', 'Always', 'Only if the first test passes', 'Larger cyclic dependency structures can still saturate capacity.'),
   ('Why is the deadlocking example not executed here?', 'It would wait without a valid completion path', 'Because futures cannot fail', 'Because sequential code is forbidden', 'An unsafe unbounded wait is explained and repaired, not launched.')],
  'Block a worker on a child that needs the same exhausted worker capacity.', 'Keep dependencies coordinated outside the saturated pool.',
  'The owner waits while the worker remains free to execute both independent jobs.',
  syntax='owner submits independent work -> owner receives results -> owner combines stages')

L(3, '6. Reuse futures while preserving the underlying model',
  'Compare thread/process results without equating their sharing and transfer rules.',
  [('Common futures interface', 'Both executor types expose submit, map and Future results. Threads still share process objects; process jobs still cross a serialization/import boundary.')],
  "A common coordination interface makes code easier to compare, but it does not erase execution semantics. A closure and live client suitable for a thread are not automatically transferable to a spawned process. Process workers still need importable definitions.\n\nThe example maps the same pure function through both executor types and checks identical complete results. It deliberately makes no speed claim for these tiny jobs. The CPU benchmark earlier measures complete lifetimes separately.\n\nBounded submission, result pairing, error delivery and owner cleanup remain useful for either model. The final project uses these principles inside an async coordinator, with a small number of awaited process calls rather than flooding the pool with every record at once.",
  G('import multiprocessing as mp\nfrom concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor\nfrom workers import square\nvalues = list(range(6))\nwith ThreadPoolExecutor(max_workers=2) as pool:\n    threaded = list(pool.map(square, values))\nwith ProcessPoolExecutor(max_workers=2, mp_context=mp.get_context("spawn")) as pool:\n    processed = list(pool.map(square, values))\nprint("Equal output:", threaded == processed)\nprint("Values:", processed)'),
  'State a difference that the shared interface does not remove.',
  'print("Threads: ordinary in-process objects can be shared")\nprint("Spawn processes: importable targets and explicit data transfer")',
  'Confirm a future failure is not converted into a normal result by the executor type.',
  'from concurrent.futures import ThreadPoolExecutor\nfrom workers import fail_job\nwith ThreadPoolExecutor(max_workers=1) as pool:\n    f = pool.submit(fail_job, "preserve failure")\n    try: f.result()\n    except ValueError: print("Failure preserved")',
  [('Does the shared Future API make a live HTTP client transferable to spawn workers?', 'No', 'Always', 'Only for small responses', 'Resource ownership and serialization constraints remain.'),
   ('Does equal output alone prove equal performance?', 'No', 'Always', 'Only with six jobs', 'Correctness parity is necessary for comparison, not a timing measurement.')],
  'Assume interface similarity makes state ownership or performance identical.', 'Share coordination patterns while respecting each execution boundary.',
  'Both implementations compute the same six squares; timings are intentionally not inferred from that fact.',
  syntax='executor choice changes execution, not the need for identity, errors and ownership',
  diagram=('Bounded futures with coordinator-owned dependencies', ['Owner pulls only an allowed submission window', 'Executor runs a fixed worker budget', 'Ready futures carry values or exceptions with ids', 'Consumer progress permits window refill', 'Owner resolves dependencies and joins the executor'], 'Worker count and queued-future count are separate limits. Waiting timeouts do not forcibly stop running calls, and dependent work must not require the same saturated capacity.'))
